import openpyxl, json
wb = openpyxl.load_workbook('inputs/delivery.xlsx', data_only=False)
for ws in wb.worksheets:
    print('SHEET', ws.title, ws.max_row, ws.max_column)
    for r in ws.iter_rows(min_row=1, max_row=4, max_col=2):
        for c in r:
            print(ws.title, c.coordinate, repr(c.value), c.data_type, c.number_format)

